<template>
  <section class="platform-actions">
    <div class="action-toolbar"><el-button size="small" type="primary" :loading="busy" @click="refresh">查询平台最新状态与可用操作</el-button><el-button v-hasPermi="['order:refund:config']" size="small" @click="configure">本店铺平台授权设置</el-button></div>
    <p class="hint">上次主动查询 {{ context.checked_at || '尚未查询' }}。列表与详情读取已保存结果；操作提交前会再次核对平台申请版本。</p>
    <el-alert v-if="error" :title="error" type="warning" :closable="false" show-icon />
    <div v-if="context.checked_at" class="action-toolbar"><el-button v-for="option in actions" :key="option.value" v-hasPermi="['order:refund:execute']" size="small" :disabled="!Number(capability.write_enabled) || closed || amountBlocked(option.value)" :title="amountBlocked(option.value) ? '请先处理申请金额冲突' : ''" @click="open(option.value)">{{ option.label }}</el-button><el-button size="small" @click="messages">查看平台留言</el-button></div>
    <el-alert v-if="(refund.automatic_flow || {}).last_message" :title="'自动流程：'+refund.automatic_flow.last_message" :type="refund.automatic_flow.state==='MANUAL'?'warning':'info'" :closable="false" /><el-button v-if="(refund.automatic_flow || {}).state==='MANUAL'" size="small" @click="retryFlow">重新检查自动流程</el-button>
    <p v-if="context.response_deadline" class="hint">平台本次响应截止：{{ context.response_deadline }}。本地挂起不会延长平台处理时限。</p>
    <p v-if="context.checked_at" class="hint">查询：{{ Number(capability.read_enabled) ? '已启用' : '未启用' }} · 业务操作：{{ Number(capability.write_enabled) ? '已启用' : '未启用' }} · 付款：{{ Number(capability.payment_enabled) && capability.payment_authorized ? '已配置子账号' : '未就绪' }}</p>
    <el-alert v-for="(tip,index) in restrictions" :key="index" :title="tip" type="info" :closable="false" />
    <el-dialog :title="actionLabel" :visible.sync="visible" width="650px" append-to-body :close-on-click-modal="false">
      <el-alert :title="action==='PAY' ? '将向平台提交本退款的实际付款' : '本次操作将提交至平台'" :description="'平台退款单 '+refund.refund_id+'；采用申请金额 '+money(refund.refund_fee)+'。仓库处理结果和平台资金结果分别核对。'" type="info" :closable="false" />
      <el-form label-width="120px" size="small" class="operation-form">
        <el-form-item v-if="['AGREE_RETURN','NEGOTIATE_SUBMIT'].includes(action)" label="平台退回地址" required><el-select v-model="form.seller_address_id" filterable placeholder="选择平台返回的退货地址" style="width:100%"><el-option v-for="address in addresses" :key="address.value" :value="address.value" :label="address.label" /></el-select><p v-if="!addresses.length" class="hint">平台尚未返回可用退货地址，请核对店铺地址及接口权限。</p></el-form-item>
        <template v-if="['REFUSE','REFUSE_RETURN'].includes(action)"><el-form-item label="平台拒绝原因" required><el-select v-model="form.refuse_reason_id" filterable style="width:100%" @change="proofStrategy"><el-option v-for="reason in reasons" :key="reason.value" :value="reason.value" :label="reason.label" /></el-select></el-form-item><p class="hint">提交前校验平台是否要求先协商；拒绝不等于申请关闭，不会自动恢复已取消的发货安排。</p></template>
        <template v-if="action==='NEGOTIATE_SUBMIT'"><el-form-item label="平台协商方案" required><el-select v-model="form.negotiate_type" style="width:100%"><el-option v-for="option in negotiationTypes" :key="option.value" :value="option.value" :label="option.label" /></el-select></el-form-item><el-form-item label="协商原因"><el-select v-model="form.reason_id" clearable style="width:100%"><el-option v-for="reason in reasons" :key="reason.value" :value="reason.value" :label="reason.label" /></el-select></el-form-item><p v-if="!negotiationTypes.length" class="hint">平台未提供可用协商方案，请到平台核对当前申请的协商条件。</p></template>
        <template v-if="action==='PAY' && !Number(capability.ignore_code)"><el-form-item label="短信验证码" required><el-input v-model.trim="form.code" maxlength="16" autocomplete="off" show-password /><el-button type="text" :loading="busy" @click="requestCode">请求本次付款验证码</el-button></el-form-item></template>
        <el-form-item v-if="action==='INTERCEPT_FEEDBACK'" label="实际物流结果" required><el-select v-model="form.logistic_status" style="width:100%"><el-option v-for="state in transportStates" :key="state.value" :value="state.value" :label="state.label" /></el-select></el-form-item>
        <template v-if="action==='RETURN_LOGISTICS'"><el-form-item label="平台快递公司编码" required><el-input v-model.trim="form.logistics_company_code" maxlength="100" /></el-form-item><el-form-item label="寄回运单号" required><el-input v-model.trim="form.logistics_waybill_no" maxlength="100" /></el-form-item></template>
        <el-form-item label="处理说明 / 依据" required><el-input v-model.trim="form.reason" type="textarea" :maxlength="action==='MESSAGE' ? 130 : 200" show-word-limit /></el-form-item>
        <el-alert v-if="proofHint" :title="proofHint" type="info" :closable="false" />
        <el-form-item v-if="['REFUSE','REFUSE_RETURN','MESSAGE','NEGOTIATE_SUBMIT'].includes(action)" label="平台凭证图片" :required="action!=='NEGOTIATE_SUBMIT'"><input type="file" accept="image/png,image/jpeg,image/gif" @change="proof"><p class="hint">JPG、PNG、GIF，拒绝凭证不超过130000字节。凭证随本次操作提交至平台。</p></el-form-item>
        <el-form-item><el-checkbox v-model="form.confirmed">已核对本退款、操作范围、金额及平台处理依据</el-checkbox></el-form-item>
      </el-form>
      <span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :disabled="!form.confirmed || (action==='NEGOTIATE_SUBMIT' && !form.negotiate_type)" :loading="busy" @click="submit">提交平台</el-button></span>
    </el-dialog>

    <el-dialog title="平台退款留言" :visible.sync="messagesVisible" width="650px" append-to-body><el-table :data="messageRows" size="small" empty-text="尚无平台留言或平台未返回留言"><el-table-column prop="content" label="留言" min-width="280" /><el-table-column prop="created" label="时间" width="170" /></el-table></el-dialog>
  </section>
</template>
<script>
import request from '@/utils/request'
import { money } from './orderAmounts'
import { refundAmountConflict } from './refundAmountPresentation'
const actions = [{ value: 'AGREE_RETURN', label: '同意退货' }, { value: 'REVIEW', label: '审核同意退款' }, { value: 'PAY', label: '确认退款付款' }, { value: 'NEGOTIATE_SUBMIT', label: '先协商处理' }, { value: 'REFUSE', label: '拒绝退款' }, { value: 'REFUSE_RETURN', label: '拒绝退货' }, { value: 'INTERCEPT', label: '申请在途拦截' }, { value: 'INTERCEPT_FEEDBACK', label: '回告物流结果' }, { value: 'CANCEL_FEEDBACK', label: '回告已取消发货' }, { value: 'RETURN_LOGISTICS', label: '补填已实收的寄回物流' }, { value: 'MESSAGE', label: '提交留言与凭证' }]
function objects(value, predicate, result = [], depth = 0) { if (!value || typeof value !== 'object' || depth > 10 || result.length >= 100) return result; if (!Array.isArray(value) && predicate(value)) result.push(value); Object.values(value).forEach(item => objects(item, predicate, result, depth + 1)); return result }
function options(value, keys) { return objects(value, row => keys.some(key => row[key] != null) && [row.name, row.text, row.title, row.reason_name, row.reason_text, row.refuse_reason, row.addr, row.address].some(Boolean)).map(row => ({ value: String(row[keys.find(key => row[key] != null)]), label: [row.name || row.text || row.title || row.reason_name || row.reason_text || row.refuse_reason || row.contact_name, row.addr || row.address].filter(Boolean).join(' · ') })) }
export default {
  name: 'RefundPlatformActions', props: { refund: { type: Object, required: true } }, data: () => ({ actions, busy: false, error: '', proofHint: '', visible: false, action: '', form: {}, liveContext: null, reasons: [], addresses: [], negotiationTypes: [], messagesVisible: false, messageRows: [], transportStates: [{ value: 'DELIVERY_INTERCEPT_SUCCESS', label: '快递已确认拦截成功' }, { value: 'DELIVERY_INTERCEPT_FAILED', label: '快递拦截失败' }, { value: 'BUYER_REFUSE_SIGN', label: '买家已拒签' }, { value: 'LOGISTICS_RETURNING', label: '物流退回中' }, { value: 'RETURN_LOGISTIC_SELLER_CONSIGN', label: '商家已签收退回物流' }] }),
  computed: { context() { return this.liveContext || this.refund.platform_context || {} }, capability() { return this.context.capability || {} }, closed() { return ['SUCCESS', 'CLOSED'].includes((this.refund.platform || {}).platform_status) }, actionLabel() { return (actions.find(action => action.value === this.action) || {}).label || '平台操作' }, restrictions() { const blocked = (this.context.allowed || {}).not_allowed_operations || {}; const rows = Array.isArray(blocked) ? blocked : blocked.operation || []; return rows.map(row => row.tips).filter(Boolean) } },
  watch: { 'refund.id'() { this.liveContext = null; this.visible = false; this.error = '' }, 'refund.channel_id'() { this.liveContext = null } },
  methods: {
    money,
    amountBlocked(action) { return !!refundAmountConflict(this.refund) && ['AGREE_RETURN', 'REVIEW', 'PAY', 'PAY_CODE'].includes(action) },
    async refresh() { this.busy = true; this.error = ''; try { const response = await request({ url: `/order/refunds/business/${this.refund.id}/platform/refresh`, method: 'post' }); this.liveContext = response.data; this.$emit('refresh') } catch (error) { this.error = error.message || '平台查询未完成，请核对接口设置' } finally { this.busy = false } },
    async information(action, params) { return (await request({ url: `/order/refunds/business/${this.refund.id}/platform/information/${action}`, params })).data },
    async open(action) { if (this.amountBlocked(action)) { this.$message.warning('请先处理平台申请金额冲突'); return } this.action = action; this.form = { reason: '', confirmed: false }; this.error = ''; this.visible = true; try { if (['AGREE_RETURN', 'NEGOTIATE_SUBMIT'].includes(action)) this.addresses = options(await this.information('ADDRESSES'), ['contact_id', 'address_id']); if (['REFUSE', 'REFUSE_RETURN'].includes(action)) { this.reasons = options(await this.information('REASONS'), ['reason_id', 'refuse_reason_id']) } if (action === 'NEGOTIATE_SUBMIT') { const info = await this.information('NEGOTIATE_RENDER'); this.negotiationTypes = options(info, ['negotiate_type', 'type_code']); this.reasons = options(info, ['reason_id']); const addresses = options(info, ['address_id', 'contact_id']); if (addresses.length) this.addresses = addresses } } catch (error) { this.error = error.message || '平台辅助资料未取得' } },
    async proofStrategy() { const result = await this.information('PROOF', { refuse_reason_id: this.form.refuse_reason_id }); this.proofHint = String((result.result_data || {}).example_description || '').replace(/<[^>]*>/g, ' ') },
    async proof(event) { const file = event.target.files[0]; if (!file) return; const maximum = ['REFUSE', 'REFUSE_RETURN'].includes(this.action) ? 130000 : 512000; if (file.size > maximum || !['image/jpeg', 'image/png', 'image/gif'].includes(file.type)) { this.$message.error('凭证图片格式或大小不符合当前接口要求'); event.target.value = ''; return } const reader = new FileReader(); reader.onload = () => this.$set(this.form, 'proof_base64', String(reader.result).split(',')[1]); reader.readAsDataURL(file) },
    async submit() { if (this.amountBlocked(this.action)) { this.$message.warning('请先处理平台申请金额冲突'); return } this.busy = true; this.error = ''; try { const args = { ...this.form }; delete args.reason; delete args.confirmed; if (['REFUSE', 'REFUSE_RETURN'].includes(this.action)) args.refuse_message = this.form.reason; if (this.action === 'MESSAGE') args.content = this.form.reason; if (this.action === 'INTERCEPT_FEEDBACK') args.fail_reason = this.form.reason; if (this.action === 'NEGOTIATE_SUBMIT') { args.address_id = args.seller_address_id; delete args.seller_address_id; args.negotiate_text = this.form.reason; args.negotiate_version = 'newNegotiate' } await request({ url: `/order/refunds/business/${this.refund.id}/platform/actions/${this.action}`, method: 'post', data: { control_version: this.refund.control_version, confirmed: this.form.confirmed, reason: this.form.reason, arguments: args }}); this.visible = false; this.$emit('refresh') } catch (error) { this.error = error.message || '平台结果未确认，请查询原操作' } finally { this.busy = false } },
    async requestCode() { if (this.amountBlocked('PAY_CODE')) { this.$message.warning('请先处理平台申请金额冲突'); return } this.busy = true; try { await request({ url: `/order/refunds/business/${this.refund.id}/platform/actions/PAY_CODE`, method: 'post', data: { control_version: this.refund.control_version, confirmed: true, reason: '请求本退款付款短信验证码', arguments: {}}}); this.$message.info('已提交验证码请求，请核对平台短信及操作记录'); this.$emit('refresh') } finally { this.busy = false } },
    async messages() { this.messageRows = objects(await this.information('MESSAGES'), row => row.content != null); this.messagesVisible = true },
    async retryFlow() { await request({ url: `/order/refunds/business/${this.refund.id}/flow/retry`, method: 'post' }); this.$emit('refresh') },
    configure() { this.$router.push({ path: '/oms-order/businessSettings', query: { channelId: this.refund.channel_id, tab: 'authorization', ...(this.refund.id ? { refundId: this.refund.id } : {}) }}) }
  }
}
</script>
<style scoped>
.platform-actions{padding:16px;margin:16px 0;border:1px solid #e4e7ed;border-radius:6px}.action-toolbar{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.action-toolbar .el-button{margin-left:0}.hint{font-size:12px;color:#75849a;line-height:1.8}.operation-form{margin-top:20px}
</style>
